library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all;
entity soqpsk_carrier_loop is port(clk,reset,valid:in std_logic; i_in,q_in:in signed(31 downto 0); phase_word:out unsigned(7 downto 0); error:out signed(31 downto 0)); end;
architecture rtl of soqpsk_carrier_loop is signal phase:unsigned(7 downto 0):=(others=>'0'); signal freq:signed(31 downto 0):=(others=>'0'); begin phase_word<=phase; process(clk) variable e:signed(31 downto 0); variable si,sq:signed(31 downto 0); begin if rising_edge(clk) then if reset='1' then phase<=(others=>'0');freq<=(others=>'0');error<=(others=>'0'); elsif valid='1' then if i_in(31)='1' then si:=to_signed(-1,32); else si:=to_signed(1,32); end if; if q_in(31)='1' then sq:=to_signed(-1,32); else sq:=to_signed(1,32); end if; e:=resize(shift_right(si*q_in-sq*i_in,8),32); error<=e; freq<=freq+shift_right(e,8); phase<=phase+unsigned(freq(31 downto 24)); end if; end if; end process; end;
